total = 0.0
while True:
    try:
        line = input().strip()
    except EOFError:
        break
    if line.lower() == "done":
        break
    if not line:
        continue
    item, price_str = line.split(":")
    item = item.strip().upper()
    price = float(price_str.strip())
    total += price
    print(f"{item}: ${price:.2f}")
print(f"TOTAL: ${total:.2f}")
